/* 指针可信性判定：还原代码里约 330 处把"未解析的裸地址"（原版地址空间里的 0x004xxxxx 等）
   当字符串指针传进来，直接 strlen/strnlen 就会踩未映射页
   （真机实测：strnlen+28 fault 0x0045b8c8 ← func_0079e45c ← DataCacheManager::initBeAttackCacheData+46）。
   判据：指针落在**本 .so 自己的映射区间**内（字面量在 .rodata）或落在高位（堆/栈/bionic）。 */
static void hw_module_probe(void) { }                  /* 仅用于取"本模块地址下界" */
static inline int hw_ptr_plausible(const void *p)
{
  unsigned long v = (unsigned long)p;
  unsigned long base = ((unsigned long)(void *)&hw_module_probe) & ~0xffful;
  if (v >= base && v < base + 0x4000000ul) return 1;   /* 本模块 .text/.rodata/.data（约 12–16MB 内）*/
  if (v >= 0x10000000ul) return 1;                     /* 堆 / 栈 / mmap / bionic */
  return 0;                                            /* 原版地址空间的裸地址等 -> 不可信 */
}

extern "C" void func_0079e45c(void *dst, const char *s, ...)   /* GNUSTL_STR_FIX: gnustl string(const char*) 构造 */
{
  if (!hw_ptr_plausible(s)) { ::new (dst) ::gnuabi::GnuString(); return; }
  unsigned long n = ::strnlen(s, 4096);                /* 可信指针：再限长，防"读不完"的巨串 */
  if (n >= 4096) { ::new (dst) ::gnuabi::GnuString(); return; }
  ::new (dst) ::gnuabi::GnuString(s, (unsigned)n);
}
